<?php
namespace App\Services;use App\Models\{Committee,CommitteeCommitment};use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;
class CommitteeCommitmentService{public function __construct(private CommitteeOperationService $operations){}public function create(Committee $committee,array $data,int $userId):CommitteeCommitment{$this->operations->ensureActive($committee);$commitment=$committee->commitments()->create(array_merge($data,['status'=>'pending','progress'=>0,'created_by'=>$userId]));$this->operations->audit($committee,'commitment_created',$commitment,$userId);return$commitment;}public function followup(CommitteeCommitment $commitment,array $data,$file,int $userId):void{DB::transaction(function()use($commitment,$data,$file,$userId){$path=$file?->store("committees/{$commitment->committee_id}/commitments/{$commitment->id}",'public');$commitment->followups()->create(array_merge($data,['evidence_path'=>$path,'created_by'=>$userId]));$status=$data['progress']>=100?'completed':($data['progress']>0?'in_progress':'pending');$commitment->update(['progress'=>$data['progress'],'status'=>$status,'completed_at'=>$status==='completed'?now():null,'evidence_path'=>$path?:$commitment->evidence_path]);$this->operations->audit(Committee::findOrFail($commitment->committee_id),$status==='completed'?'commitment_completed':'commitment_updated',$commitment,$userId,['progress'=>$data['progress']]);});}}
